import type { PuzzleSlot, TaskInfo } from "../../types";

export const taskTemplate = (roundSlug: string): Partial<PuzzleSlot> => ({
  unlocked_if: { round_unlocked: roundSlug },
  prize: 3,
  task_info: {
    submission_type: "auto",
  },
});

export const manualTaskTemplate = (
  roundSlug: string,
  overrideTaskInfo?: Partial<TaskInfo>,
): Partial<PuzzleSlot> => ({
  ...taskTemplate(roundSlug),
  task_info: {
    submission_type: "manual",
    ...overrideTaskInfo,
  },
});

export const eventTaskTemplate = (
  roundSlug: string,
  overrideTaskInfo?: Partial<TaskInfo>,
): Partial<PuzzleSlot> => {
  return {
    ...taskTemplate(roundSlug),
    task_info: {
      submission_type: "event" as const,
      ...overrideTaskInfo,
    },
  };
};

export const interactiveTaskTemplate = (
  roundSlug: string,
): Partial<PuzzleSlot> => ({
  ...taskTemplate(roundSlug),
  task_info: {
    submission_type: "interactive",
  },
});

export const gameworldTaskTemplate = (
  roundSlug: string,
  overrideTaskInfo?: Partial<TaskInfo>,
): Partial<PuzzleSlot> => ({
  ...taskTemplate(roundSlug),
  task_info: {
    submission_type: "gameworld",
    ...overrideTaskInfo,
  },
});
