export const generatePuzzleSlotsFromBanners = (
  puzzleSlotToSlug: Record<string, string>,
): GachaPuzzleSlot[] => {
  const puzzleSlots: GachaPuzzleSlot[] = [];

  // Iterate through each banner and create puzzle slots for puzzleSlot1 and puzzleSlot2
  Object.entries(BANNERS).forEach(([_, banner]) => {
    // Create puzzle slot for puzzleSlot1
    for (const slot of [banner.left_puzzle_slot, banner.right_puzzle_slot]) {
      const slug = puzzleSlotToSlug[slot];
      if (slug) {
        puzzleSlots.push({
          id: slot,
          unlockable_if: banner.unlockable_if,
          unlocked_if: { gate_satisfied: `gcg${slot.slice(-2)}` },
          slug: slug,
          is_meta: false,
          banner: banner,
        });
      }
    }
  });
  puzzleSlots.push({
    id: "meta",
    unlocked_if: { round_unlocked: "fates_thread_casino", puzzles_solved: 7 },
    is_meta: true,
    slug: "to_pull_or_not_to_pull",
  });

  return puzzleSlots;
};
