import { dontLeakThis } from "@hunt/anti-leak";
import { OVERWORLD_CAPSTONE_SLOTS } from "../../overworld/constants";
import { BANNERS, generatePuzzleSlotsFromBanners } from "./banner";
import { CLUE_ORDER } from "./pull_order";
import type { GachaRound, GachaPuzzleSlot, Pull, PullError } from "./types";

export const STARTING_PULLS = 40;
export const KNOWLEDGE_CHECKS_PULL_GAINS = 8;
export const HOURLIES_PULL_GAINS = 1;
export const DROP_META_PIECE_AT = 156;
export const PULL_COST_MULTIPLIER = 100;

const assert = (condition: boolean, message: string) => {
  if (!condition) {
    throw new Error(message);
  }
};

const BANNER_UNLOCK_GATES = dontLeakThis(
  Object.values(BANNERS).map((banner) => ({
    id: `gacha_banner_${banner.slug}_unlocked`,
    title: banner.name,
    show_notification: false,
  })),
);

export const bannerUnlockGateId = (bannerSlug: string) =>
  `gacha_banner_${bannerSlug}_unlocked`;

export const PUZZLE_SLOT_TO_SLUG: Record<string, string> = dontLeakThis({
  ftcp01: "meme_scenes",
  ftcp02: "common_scenes",
  ftcp03: "charfactor",
  ftcp04: "as_the_fly_crows",
  ftcp05: "building_blocks",
  ftcp06: "easy_as_1_22_333",
  ftcp07: "plots",
  ftcp08: "graphs",
  ftcp09: "hear_me_out",
  ftcp10: "goku",
});

// these gates are cleared when the shell is pulled
export const SHELL_PULL_GATES = Array.from({ length: 10 }, (_, i) => {
  const slotId = `ftcp${String(i + 1).padStart(2, "0")}`;
  const puzzleName = PUZZLE_SLOT_TO_SLUG[slotId];
  return {
    id: `gcg${String(i + 1).padStart(2, "0")}`,
    internal_description: `${puzzleName}'s shell was pulled`,
    show_notification: true,
  };
});

const GACHA_PUZZLES: GachaPuzzleSlot[] = dontLeakThis(
  generatePuzzleSlotsFromBanners(PUZZLE_SLOT_TO_SLUG),
);

export const GACHA: GachaRound = dontLeakThis({
  slug: "fates_thread_casino",
  title: "Fate's Thread Casino",
  final_puzzle_slot: "meta",
  keeper_slug: "keeper_of_fate",
  puzzles: GACHA_PUZZLES,
  gates: [
    ...SHELL_PULL_GATES,
    ...BANNER_UNLOCK_GATES,
    {
      id: "gacha_freed",
      title: "Gacha Slot Freed",
      satisfied_if: {
        slot_unlocked: "meta",
      },
    },
  ],
  interactions: [
    {
      id: "ftcc01",
      title: "Fate's Thread Casino Intro",
      unlocked_if: { round_unlocked: "fates_thread_casino" },
      virtual: true,
    },
    {
      id: "ftcc02",
      title: "Fate's Thread Casino Outro",
      unlocked_if: { slot_solved: "meta" },
      virtual: true,
    },
  ],
  // These are AND conditions.
  unlockable_if: [
    { puzzles_solved: 6, slots: OVERWORLD_CAPSTONE_SLOTS },
    // To enforce linearity of unlocks, the Nth dimension must be unlocked before the (N+1)th dimension.
    { round_unlocked: "atlas_of_mosaics" },
    // We have a dimension width of 3 (including overworld), so we need to satisfy 2 out of 4 to be able to unlock this dimension
    {
      gates_satisfied: 2,
      gates: [
        "kingdom_freed",
        "alphabet_freed",
        "tile_freed",
        "hyperbolic_space_freed",
      ],
    },
  ],
  unlock_cost: 3,
});

export const GACHA_META_SLUG =
  GACHA_PUZZLES.find((puzzle) => puzzle.id === GACHA.final_puzzle_slot)?.slug ||
  "";

export const TOTAL_CLUES_BY_BANNER: Record<string, number> = Object.entries(
  BANNERS,
).reduce<Record<string, number>>((acc, [banner_slug, banner]) => {
  const left_puzzle_slug = PUZZLE_SLOT_TO_SLUG[banner.left_puzzle_slot];
  const right_puzzle_slug = PUZZLE_SLOT_TO_SLUG[banner.right_puzzle_slot];

  const left_clue_order = CLUE_ORDER[left_puzzle_slug] || [];
  const right_clue_order = CLUE_ORDER[right_puzzle_slug] || [];

  const all_clue_ids = new Set<string>();
  left_clue_order.forEach((clue) => {
    if (clue.type === "clue") {
      all_clue_ids.add(clue.id);
    }
  });
  right_clue_order.forEach((clue) => {
    if (clue.type === "clue") {
      all_clue_ids.add(clue.id);
    }
  });
  acc[banner_slug] = all_clue_ids.size;
  return acc;
}, {});

const CLUE_ORDER_BY_BANNER: Record<string, Pull[]> = dontLeakThis(
  Object.entries(BANNERS).reduce<Record<string, Pull[]>>(
    (acc, [banner_slug, banner]) => {
      const encoded_message = banner.encoded_message; // merge pre-determined pulls from two puzzles, plus two shell pulls
      const pull_order = [];
      let left_index = 0;
      let right_index = 0;
      for (let i = 0; i < DROP_META_PIECE_AT; i++) {
        const side = encoded_message[i % encoded_message.length];
        if (banner.left_shell_pulled_at.includes(i)) {
          assert(
            side === 0,
            `left shell pull should be on left side for ${banner_slug}`,
          );
          pull_order.push({
            type: "shell" as const,
            puzzle_slug: PUZZLE_SLOT_TO_SLUG[banner.left_puzzle_slot],
            gate_slug: `gcg${banner.left_puzzle_slot.slice(-2)}`,
          });
        } else if (banner.right_shell_pulled_at.includes(i)) {
          assert(
            side === 1,
            `right shell pull should be on right side for ${banner_slug}`,
          );
          pull_order.push({
            type: "shell" as const,
            puzzle_slug: PUZZLE_SLOT_TO_SLUG[banner.right_puzzle_slot],
            gate_slug: `gcg${banner.right_puzzle_slot.slice(-2)}`,
          });
        } else {
          if (side === 0) {
            const puzzle_slug = PUZZLE_SLOT_TO_SLUG[banner.left_puzzle_slot];
            const clue_order = CLUE_ORDER[puzzle_slug];
            pull_order.push({
              ...clue_order[left_index % clue_order.length],
              puzzle_slug: puzzle_slug,
            });
            left_index++;
          } else {
            const puzzle_slug = PUZZLE_SLOT_TO_SLUG[banner.right_puzzle_slot];
            const clue_order = CLUE_ORDER[puzzle_slug];
            pull_order.push({
              ...clue_order[right_index % clue_order.length],
              puzzle_slug: puzzle_slug,
            });
            right_index++;
          }
        }
      }
      acc[banner_slug] = pull_order;
      return acc;
    },
    {},
  ),
);

export function generatePull(
  banner_slug: string,
  event_number: number,
): Pull | PullError {
  const banner = BANNERS[banner_slug];
  if (!banner) {
    throw new Error(`banner ${banner_slug} not found`);
  }

  if (event_number === DROP_META_PIECE_AT - 1) {
    return {
      type: "clue",
      id: `meta-${banner_slug}`,
      puzzle_slug: GACHA_META_SLUG,
    };
  } else if (event_number >= DROP_META_PIECE_AT) {
    return {
      type: "empty",
    };
  }

  const pull_order = CLUE_ORDER_BY_BANNER[banner_slug];
  if (pull_order?.length === 0) {
    throw new Error(`pull order for banner ${banner_slug} not found`);
  }

  if (event_number >= pull_order.length) {
    throw new Error(
      `pull should be disabled on ${banner_slug} after ${pull_order.length}`,
    );
  } else {
    return pull_order[event_number];
  }
}
