for (let direction = 0; direction < 6; direction++) {
  milkTeaLevelBuilder.addTileToBank(
    `milk-tea-stick-${direction}`,
    3e3,
    {
      renderer: "milk-tea-tile",
      props: { direction, isLine: false }
    },
    "milktea-stick"
  );
  if (direction >= 3) {
    continue;
  }
  milkTeaLevelBuilder.addTileToBank(
    `milk-tea-line-${direction}`,
    3e3,
    {
      renderer: "milk-tea-tile",
      props: { direction, isLine: true }
    },
    "milktea-line"
  );
  for (let junctionDirection = 0; junctionDirection < 6; junctionDirection++) {
    if (junctionDirection === direction || junctionDirection === direction + 3) {
      continue;
    }
    milkTeaLevelBuilder.addTileToBank(
      `milk-tea-junction-${direction}-${junctionDirection}`,
      3e3,
      {
        renderer: "milk-tea-tile",
        props: { direction, junctionDirection, isLine: false }
      },
      "milktea-junction"
    );
  }
}
