/**
 * The cost in RP for hints in dimension rounds.
 */
export const DIMENSION_HINT_COST = 2;

/**
 * Type for hint resources (puzzles, rounds, or banners).
 * Matches the HintResource type from @hunt/public-client.
 */
export type HintResourceType = {
  type: "puzzle" | "round" | "banner";
  slug: string;
};

/**
 * Calculate the RP cost for a hint request based on the resource type.
 * - Puzzles in dimension rounds cost DIMENSION_HINT_COST
 * - Dimension rounds cost DIMENSION_HINT_COST
 * - Banners always cost DIMENSION_HINT_COST
 * - Everything else costs 0
 */
export function getHintCost(hintResource: HintResourceType): number {
  switch (hintResource.type) {
    case "puzzle": {
      // Find the round that contains this puzzle
      const roundSlug = HUNT.rounds.find((r) =>
        r.puzzles.some((p) => p.slug === hintResource.slug),
      )?.slug;
      return roundSlug && DIMENSION_ROUND_SLUGS.includes(roundSlug)
        ? DIMENSION_HINT_COST
        : 0;
    }
    case "round":
      return DIMENSION_ROUND_SLUGS.includes(hintResource.slug)
        ? DIMENSION_HINT_COST
        : 0;
    case "banner":
      return DIMENSION_HINT_COST;
    default:
      return 0;
  }
}

